export type LogoutCommandOptions = Pick<Config,
| 'configDir'
| 'dir'
| 'authConfig'
> & {
  registry?: string
}

export async function handler (
  opts: LogoutCommandOptions
): Promise<string> {
  return logout({ opts })
}

export interface LogoutFetchResponse {
  ok: boolean
  status: number
  text: () => Promise<string>
}

export interface LogoutContext {
  fetch: (url: string, init?: RequestInit) => Promise<LogoutFetchResponse>
  globalInfo: (message: string) => void
  globalWarn: (message: string) => void
  readIniFile: (configPath: string) => Promise<Record<string, unknown>>
  writeIniFile: (configPath: string, settings: Record<string, unknown>) => Promise<void>
}

export const DEFAULT_CONTEXT: LogoutContext = {
  fetch,
  globalInfo,
  globalWarn,
  readIniFile,
  writeIniFile,
}

export interface LogoutOpts {
  configDir: string
  dir: string
  authConfig: Record<string, string>
  registry?: string
}

export interface LogoutParams {
  context?: LogoutContext
  opts: LogoutOpts
}

export async function logout ({ context = DEFAULT_CONTEXT, opts }: LogoutParams): Promise<string> {
  const registry = normalizeRegistryUrl(opts.registry ?? 'https://registry.npmjs.org/')
  const authTokenKey = `${getRegistryConfigKey(registry)}:_authToken`

  const token = opts.authConfig[authTokenKey]
  if (!token) {
    throw new NotLoggedInError(registry)
  }

  const tokenRevoked = await revokeToken({ context, registry, token })

  const configPath = path.join(opts.configDir, 'auth.ini')
  const settings = await safeReadIniFile(context.readIniFile, configPath)

  if (settings != null && authTokenKey in settings) {
    delete settings[authTokenKey]
    await context.writeIniFile(configPath, settings)
    return `Logged out of ${registry}`
  }

  // The token exists in the resolved auth config but not in the auth.ini file
  // that this command manages. It cannot be cleaned up locally here.
  if (!tokenRevoked) {
    throw new LogoutFailedError(registry)
  }

  context.globalWarn(`The auth token for ${registry} was not found in ${configPath}`)
  context.globalWarn('The token was revoked on the registry but must be removed manually')

  return `Logged out of ${registry}`
}

interface RevokeTokenParams {
  context: Pick<LogoutContext, 'fetch' | 'globalInfo'>
  registry: string
  token: string
}

/**
 * Revokes the auth token on the registry. Returns whether the revocation
 * succeeded. Failures are reported via globalInfo but never thrown, so that
 * the local auth.ini can still be cleaned up.
 */
async function revokeToken ({ context, registry, token }: RevokeTokenParams): Promise<boolean> {
  const revokeUrl = `${registry}-/user/token/${encodeURIComponent(token)}`

  try {
    const response = await context.fetch(revokeUrl, {
      method: 'DELETE',
      headers: {
        Authorization: `Bearer ${token}`,
      },
    })

    if (!response.ok) {
      context.globalInfo(`Registry returned HTTP ${response.status} when revoking token`)
      return false
    }

    return true
  } catch {
    context.globalInfo('Could not reach the registry to revoke the token')
    return false
  }
}

function getRegistryConfigKey (registryUrl: string): string {
  const url = new URL(registryUrl)
  return `//${url.host}${url.pathname}`
}

async function safeReadIniFile (
  readIniFile: LogoutContext['readIniFile'],
  configPath: string
): Promise<Record<string, unknown> | undefined> {
  try {
    return await readIniFile(configPath)
  } catch (err: unknown) {
    if (util.types.isNativeError(err) && 'code' in err && err.code === 'ENOENT') return undefined
    throw err
  }
}

class NotLoggedInError extends PnpmError {
  constructor (registry: string) {
    super('NOT_LOGGED_IN', `Not logged in to ${registry}, so can't log out`)
  }
}

class LogoutFailedError extends PnpmError {
  constructor (registry: string) {
    super('LOGOUT_FAILED', `Failed to log out of ${registry}. The token was not found in the local auth.ini file and may still need to be revoked on the registry.`)
  }
}
